'use strict';

const fs = require('fs');
const n = Number(fs.readFileSync(0, 'utf8').trim());

if (n === 2) {
  console.log(-1);
} else if (n % 2 === 1) {
  const rows = [];
  for (let i = 0; i < n; i++) {
    const row = [];
    for (let j = 0; j < n; j++) row.push(i * n + j + 1);
    rows.push(row.join(' '));
  }
  console.log(rows.join('\n'));
} else {
  const t = n * (n - 1) / 2;
  const scale = t + 1;
  const values = Array.from({ length: n - 1 }, (_, i) => i + 1);
  values.push(t);

  const rows = [];
  for (const a of values) {
    rows.push(values.map(b => a * scale + b).join(' '));
  }
  console.log(rows.join('\n'));
}
